function f(t,n=2){if(!t||t<=0||isNaN(t))return"0 B";const o=1024,a=n<0?0:n,r=["B","KB","MB","GB","TB","PB"],i=Math.floor(Math.log(t)/Math.log(o)),e=Math.min(i,r.length-1);return`${parseFloat((t/Math.pow(o,e)).toFixed(a))} ${r[e]}`}function u(t){if(!t)return"-";const n=new Date(t);return isNaN(n.getTime())?"-":n.toLocaleDateString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit"})}function c(t){if(!t)return"-";const n=new Date(t);return isNaN(n.getTime())?"-":n.toLocaleString("zh-CN",{hour12:!1})}export{u as a,c as b,f};
